const raw = items[0].json || {};
const p = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const limpio = (v, max) => String(v === undefined || v === null || v === '' ? 'desconocido' : v).slice(0, max || 300);

const cabeceras = p.cabeceras && typeof p.cabeceras === 'object'
  ? Object.entries(p.cabeceras).map(([k, v]) => '  ' + limpio(k, 60) + ': ' + limpio(v, 200)).join('\n')
  : '  (sin cabeceras)';

const description = [
  'Acceso al endpoint trampa (honeypot) /api/admin/reset-all.',
  'Esa ruta no hace nada real: nadie legitimo la usa, asi que se trata de un intento activo de intrusion.',
  '',
  'IP de origen: ' + limpio(p.ip),
  'Cadena X-Forwarded-For: ' + limpio(p.cadenaXForwardedFor),
  'User-Agent: ' + limpio(p.userAgent),
  'Metodo: ' + limpio(p.metodo),
  'Ruta solicitada: ' + limpio(p.ruta),
  'Fecha (UTC): ' + limpio(p.fecha),
  'Registro en tabla auditorias (id): ' + limpio(p.auditoriaId),
  '',
  'Cabeceras recibidas (Authorization y Cookie sin valor):',
  cabeceras,
  '',
  'Accion sugerida: ver el protocolo de respuesta a incidentes (bloquear la IP, revisar auditorias y rotar secretos si hay indicios de acceso previo).'
].join('\n');

return [{
  json: {
    ip: limpio(p.ip),
    auditoriaId: p.auditoriaId === undefined ? null : p.auditoriaId,
    summary: '[HONEYPOT] Intento de acceso a /api/admin/reset-all desde ' + limpio(p.ip, 60),
    description,
    priorityId: 50,
    severityId: 60
  }
}];

const issue = (items[0].json && items[0].json.issue) || {};
const origen = $('Armar Incidente').first().json || {};
console.log(JSON.stringify({
  ts: new Date().toISOString(),
  source: 'n8n-honeypot',
  workflow: $workflow.name,
  executionId: $execution.id,
  ticketMantis: issue.id || null,
  ip: origen.ip || null,
  auditoriaId: origen.auditoriaId
}));
return items;

const entries = Array.isArray(items) ? items : [items];
for (const item of entries) {
  const data = item.json || {};
  const err = data.error || data;
  const nodeName = (data.node && data.node.name) || data.nodeName || data.node || 'desconocido';
  console.error(JSON.stringify({
    ts: new Date().toISOString(),
    source: 'n8n-honeypot-error-node',
    workflow: $workflow.name,
    executionId: $execution.id,
    node: typeof nodeName === 'string' ? nodeName : JSON.stringify(nodeName),
    message: err.message || String(err),
    description: err.description || null
  }, null, 2));
}
return [];
